e(string$path,string$extension):array{if(filesize($path)>128*1024*1024)return['kind'=>'unsupported'];$zip=new ZipArchive();if($zip->open($path,ZipArchive::RDONLY)!==true)return['kind'=>'unsupported'];try{return match($extension){'docx'=>self::document($zip),'xlsx'=>self::spreadsheet($zip),'pptx'=>self::slides($zip),default=>['kind'=>'archive','entries'=>array_map(static fn(int$i):string=>$zip->getNameIndex($i)?:'',array_keys(array_fill(0,min($zip->numFiles,200),true))),'partial'=>$zip->numFiles>200],};}finally{$zip->close();}}private static function xml(ZipArchive$zip,string$entry):?DOMXPath{$stat=$zip->statName($entry);if(!$stat||$stat['size']>self::XML_LIMIT)return null;$xml=$zip->getFromName($entry,self::XML_LIMIT);if($xml===false||$xml===''||stripos($xml,'<!DOCTYPE')!==false||str_contains($xml,"\0")||!mb_check_encoding($xml,'UTF-8'))return null;$document=new DOMDocument();return$document->loadXML($xml,LIBXML_NONET|LIBXML_COMPACT|LIBXML_NOERROR|LIBXML_NOWARNING)?new DOMXPath($document):null;}private static function paragraphs(DOMXPath$xml):string{$text='';foreach($xml->query('//*[local-name()="p"]')as$paragraph){foreach($xml->query('.//*[local-name()="t" or local-name()="tab" or local-name()="br"]',$paragraph)as$part){$text.=match($part->localName){'tab'=>"\t",'br'=>"\n",default=>$part->textContent};if(strlen($text)>self::TEXT_LIMIT)return$text;}$text.="\n";if(strlen($text)>self::TEXT_LIMIT)break;}return$text;}private static function document(ZipArchive$zip):array{$xml=self::xml($zip,'word/document.xml');if(!$xml)return['kind'=>'unsupported'];$text=self::paragraphs($xml);return['kind'=>'document','text'=>mb_strcut($text,0,self::TEXT_LIMIT),'partial'=>strlen($text)>self::TEXT_LIMIT];}private static function slides(ZipArchive$zip):array{$slides=[];for($i=1;$i<=30&&($xml=self::xml($zip,"ppt/slides/slide$i.xml"));++$i){$slides[]=mb_strcut(self::paragraphs($xml),0,4096);}return$slides?['kind'=>'slides','slides'=>$slides]:['kind'=>'unsupported'];}private static functio